def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    apples = image_patch.find("apple")
    oranges = image_patch.find("orange")

    if not apples or not oranges:
        return image_patch

    apple_centers = [(a.left + a.right) / 2, (a.lower + a.upper) / 2] for a in apples]
    orange_centers = [(o.left + o.right) / 2, (o.lower + o.upper) / 2] for o in oranges]

    for apple_center in apple_centers:
        for orange_center in orange_centers:
            if abs(apple_center[0] - orange_center[0]) < 10 and abs(apple_center[1] - orange_center[1]) < 10:
                return oranges[oranges.index(next(o for o in oranges if (o.left + o.right) / 2 == orange_center[0] and (o.lower + o.upper) / 2 == orange_center[1]))]

    return image_patch

